import json
from collections import Counter
def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    others=[c for c,_ in cnt.most_common() if c!=bg]
    seg=others[0]; anc=others[-1]   # demo: seg=2,anc=7 ; test: seg=3,anc=7
    out=[r[:] for r in g]
    # runs of seg color
    horiz=[];vert=[]
    for i in range(H):
        j=0
        while j<W:
            if g[i][j]==seg:
                k=j
                while k<W and g[i][k]==seg: k+=1
                horiz.append((i,j,k-1))
                j=k
            else: j+=1
    for j in range(W):
        i=0
        while i<H:
            if g[i][j]==seg:
                k=i
                while k<H and g[k][j]==seg: k+=1
                vert.append((j,i,k-1)); i=k
            else: i+=1
    def paint(r,c,color):
        if out[r][c]==bg: out[r][c]=color
    for i,j,e in horiz:
        for col in (j,e):
            for r in range(H): paint(r,col,7)
    for j,i,e in vert:
        for row in (i,e):
            for c in range(W): paint(row,c,7)
    # anchors on bar paths -> 4
    for i,j in [(r,c) for r in range(H) for c in range(W) if out[r][c]==anc]:
        on=False
        for col in set(c for (_,_,e) in horiz for c in (col for col in (j,e)) ): pass
        brcols={h[1] for h in horiz}; brcols|={h[2] for h in horiz}
        brrows={v[1] for v in vert}; brrows|={v[2] for v in vert}
        if i in brrows or j in brcols: out[i][j]=4
    return out
