import collections
def runs(line,val):
    out=[];j=0
    while j<len(line):
        if line[j]==val:
            k=j
            while k<len(line) and line[k]==val: k+=1
            out.append((j,k-1)); j=k
        else: j+=1
    return out
def f(a):
    H=len(a);W=len(a[0])
    cnt=collections.Counter(x for r in a for x in r)
    bg=cnt.most_common(1)[0][0]
    others=sorted([c for c,_ in cnt.items() if c!=bg])
    segs=[]
    for col in others:
        for i,row in enumerate(a):
            for s,e in runs(row,col):
                if e-s+1>=2: segs.append(('h',col,i,s,e))
        for j in range(W):
            colv=[a[i][j] for i in range(H)]
            for s,e in runs(colv,col):
                if e-s+1>=2: segs.append(('v',col,s,j,e))
    inSeg=set()
    for kind,c,r0,s,e in segs:
        cells={(r0,s),(r0,e)}
        inSeg|=cells
    anchors=[(i,j,a[i][j]) for i in range(H) for j in range(W) if a[i][j]!=bg and (i,j) not in inSeg]
    acolor={a[i][j] for i,j,_ in anchors}
    assert len(acolor)==1,f'anchors multi-color {acolor}'
    bar=next(iter(acolor))
    hpts=set(); vpts=set()
    for kind,c,r0,s,e in segs:
        if kind=='h': hpts.add((s,e))   # endpoint columns
        else: vpts.add((s,e))          # endpoint rows
    out=[r[:] for r in a]
    for (c,_) in hpts:
        for rr in range(H):
            if out[rr][c]==bg: out[rr][c]=bar
    for (_,r) in vpts:
        for cc in range(W):
            if out[r][cc]==bg: out[r][cc]=bar
    for (r,c,v) in anchors:
        if (r,) in {x[0] for x in vpts} or (c,) in {x[1] for x in hpts}: out[r][c]=4
    return out
