        while st:
            y,x=st.pop()
            comp.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                q=(y+dy,x+dx)
                if 0<=q[0]<H and 0<=q[1]<W and q not in seen:
                    seen.add(q);st.append(q)
        out.append(comp)
    return out
